import styles from './tech.module.css';
import Image from 'next/image';
import content from '../../data/content.json';

const TechPage = () => {
    return (
        <div className={styles.container}>
            <div className="bg-grid"></div>

            <section className={styles.hero}>
                <div className={styles.heroTitles}>
                    <span className={styles.heroEng}>EQUIPMENT FLEET</span>
                    <h1 className={styles.heroMain}>Парк <br />оборудования</h1>
                </div>
                <p className={styles.heroLead}>
                    {content.tech.introText}
                </p>
            </section>

            <section className={styles.fleetList}>
                {content.tech.equipment.map((item: any, idx: number) => (
                    <div key={item.name} className={styles.machineCard}>
                        <div className={styles.imageCol}>
                            <div className={styles.imageBadge}>SYSTEM 0{idx + 1}</div>
                            <Image
                                src={item.image}
                                alt={item.name}
                                width={800}
                                height={600}
                                className={styles.machineImage}
                            />
                        </div>

                        <div className={styles.contentCol}>
                            <div className={styles.machineHeader}>
                                <h2 className={styles.machineName}>{item.name}</h2>
                                <div className={styles.qtyBadge}>
                                    <span className={styles.qtyLabel}>В НАЛИЧИИ:</span>
                                    <span className={styles.qtyValue}>{item.qty}</span>
                                </div>
                            </div>

                            <p className={styles.machineDesc}>{item.desc}</p>

                            <div className={styles.specSection}>
                                <div className={styles.specHeader}>
                                    <span className={styles.specLine}></span>
                                    <span className={styles.specTitle}>СПЕЦИАЛИЗАЦИЯ / APPLICATIONS</span>
                                </div>
                                <p className={styles.usageText}>{item.usage}</p>
                            </div>

                            <button className="primary-button primary-button--outline" style={{ marginTop: 'auto', width: 'fit-content' }}>
                                ТЕХНИЧЕСКАЯ КОНСУЛЬТАЦИЯ
                            </button>
                        </div>
                    </div>
                ))}
            </section>
        </div>
    );
};

export default TechPage;
